{"yol":"fiyat.js","icerik":"export let kampanyaDurumu = 'normal';

export function indirimliFiyat(fiyat, yuzde) {
  let indirimOrani = kampanyaDurumu === 'kampanya' ? yuzde / 2 : yuzde;
  return fiyat - (fiyat * indirimOrani / 100);
}"}

